solution_code:
#include <vector>
#include <set>
using namespace std;

vector<int> removeDuplicates(vector<int> v) {
    set<int> seen;
    vector<int> result;
    for (int x : v) {
        if (seen.insert(x).second) {
            result.push_back(x);
        }
    }
    return result;
}

