#include <string>
#include <vector>
#include <map>
using namespace std;

class StudentManager {
    map<string, vector<int>> students;
public:
    void addStudent(string name, vector<int> scores) {
        students[name] = scores;
    }
    double getAverage(string name) {
        if (students.find(name) == students.end()) return -1;
        auto& scores = students[name];
        double sum = 0;
        for (int s : scores) sum += s;
        return sum / scores.size();
    }
    string getTopStudent() {
        string top;
        double maxAvg = -1;
        for (auto& [name, scores] : students) {
            double avg = getAverage(name);
            if (avg > maxAvg) { maxAvg = avg; top = name; }
        }
        return top;
    }
};
